        private bool BeginInitialMainLoading()
        {
            if (_initialMainLoadingStarted || _initialMainLoadingCompleted)
                return false;

            _initialMainLoadingStarted = true;

            lock (_initialLoadLock)
            {
                _initialLoadTokens.Clear();

                _initialLoadTokens.Add("CASH");
                _initialLoadTokens.Add("HOLDINGS");
                _initialLoadTokens.Add("ORDERS");
            }

            MainLoadingMessage = "초기 계좌 / 보유종목 / 주문내역을 불러오는 중입니다...";
            IsMainLoading = true;

            return true;
        }
        private void CompleteInitialMainLoadingToken(string token)
        {
            if (!_initialMainLoadingStarted || _initialMainLoadingCompleted)
                return;

            if (string.IsNullOrWhiteSpace(token))
                return;

            bool completed;

            lock (_initialLoadLock)
            {
                _initialLoadTokens.Remove(token);
                completed = _initialLoadTokens.Count == 0;
            }

            if (!completed)
                return;

            _initialMainLoadingCompleted = true;

            Application.Current?.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    MainLoadingMessage = string.Empty;
                    IsMainLoading = false;
                }));
        }

        private void RefreshOrderHistory()
        {
            if (Application.Current != null && !Application.Current.Dispatcher.CheckAccess())
            {
                Application.Current.Dispatcher.BeginInvoke(
                    DispatcherPriority.Background,
                    new Action(RefreshOrderHistory));
                return;
            }

            var items = OrderHistory
                .Where(x => x != null)
                .ToList();

            OrderHistory.Clear();

            foreach (var order in items)
                OrderHistory.Add(order);
        }

        private void AddOrUpdateOrderHistory(OrderInfo order)
        {
            if (order == null)
                return;

            if (Application.Current != null && !Application.Current.Dispatcher.CheckAccess())
            {
                Application.Current.Dispatcher.BeginInvoke(
                    DispatcherPriority.Background,
                    new Action(() => AddOrUpdateOrderHistory(order)));
                return;
            }

            order.OrderTime = NormalizeOrderTime(order.OrderTime);

            if (string.IsNullOrWhiteSpace(order.OrderNo))
                return;

            int resolvedIncomingPrice = ResolveOrderPriceForCash(order);
            if (order.Price <= 0 && resolvedIncomingPrice > 0)
                order.Price = resolvedIncomingPrice;

            var existing = OrderHistory.FirstOrDefault(x =>
                x != null &&
                !string.IsNullOrWhiteSpace(x.OrderNo) &&
                x.OrderNo == order.OrderNo);

            if (existing == null)
            {
                OrderHistory.Add(order);
                return;
            }

            existing.TradeGroupId = order.TradeGroupId;
            existing.OrderTime = order.OrderTime;
            existing.Code = order.Code;
            existing.Name = order.Name;
            existing.OrderType = order.OrderType;
            existing.Qty = order.Qty;
            existing.ExecQty = order.ExecQty;

            // 중요:
            // 키움 미체결/주문내역에서 가격 0이 들어와도 기존 정상 주문가격을 덮어쓰면 안 된다.
            if (order.Price > 0)
                existing.Price = order.Price;
            else if (existing.Price <= 0 && resolvedIncomingPrice > 0)
                existing.Price = resolvedIncomingPrice;

            if (order.ExecPrice > 0)
                existing.ExecPrice = order.ExecPrice;

            existing.Status = order.Status;
            existing.UntradedQty = order.UntradedQty;
            existing.OrderStatus = order.OrderStatus;

            if (!string.IsNullOrWhiteSpace(order.StrategyName) &&
                (IsEmptyOrSystemOrderStrategy(existing.StrategyName) || !IsEmptyOrSystemOrderStrategy(order.StrategyName)))
            {
                existing.StrategyName = order.StrategyName;
            }

            existing.Fee = order.Fee;
            existing.Tax = order.Tax;
            existing.ParentOrderNo = order.ParentOrderNo;

            if (!string.IsNullOrWhiteSpace(order.TiRexDirection))
                existing.TiRexDirection = order.TiRexDirection;

            if (order.TiRexConfidence > 0)
                existing.TiRexConfidence = order.TiRexConfidence;

            if (order.TiRexPredictedReturn != 0)
                existing.TiRexPredictedReturn = order.TiRexPredictedReturn;
        }

