        public void OnHogaReceived(string windowId, HogaData data)
        {
            if (data == null)
                return;

            if (Context == null || string.IsNullOrWhiteSpace(Context.Code))
                return;

            if (data.Code != Context.Code)
                return;

            lock (_latestHogaLock)
            {
                _latestHogaForAutoTrade = data;
            }

            // 호가 UI는 너무 자주 갱신하지 않는다.
            if ((DateTime.Now - _lastHogaUiUpdateTime).TotalMilliseconds < 300)
                return;

            _lastHogaUiUpdateTime = DateTime.Now;


            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    if (Context == null || string.IsNullOrWhiteSpace(Context.Code))
                        return;

                    if (data.Code != Context.Code)
                        return;

                    AskList.Clear();
                    foreach (var item in data.Asks)
                        AskList.Add(item);

                    BidList.Clear();
                    foreach (var item in data.Bids)
                        BidList.Add(item);

                    TotalAskQty = data.TotalAskQty;
                    TotalBidQty = data.TotalBidQty;
                }));
        }

        private void Kiwoom_OnProgramTradeReceived(string windowId, ProgramTradeInfo trade, ProgramFlowSnapshotRecord flow)
        {
            if (trade == null || string.IsNullOrWhiteSpace(trade.Code))
                return;

            if (Context == null || string.IsNullOrWhiteSpace(Context.Code))
                return;

            if (!string.Equals(trade.Code, Context.Code, StringComparison.OrdinalIgnoreCase))
                return;

            if (flow != null)
                _autoTradeController?.UpdateProgramFlowSnapshot(flow);

            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    if (Context == null || !string.Equals(trade.Code, Context.Code, StringComparison.OrdinalIgnoreCase))
                        return;

                    ProgramTrades.Insert(0, trade);

                    while (ProgramTrades.Count > 300)
                        ProgramTrades.RemoveAt(ProgramTrades.Count - 1);

                    if (flow != null)
                        LatestProgramFlowSnapshot = flow;
                }));
        }

        private void ClearProgramTradeRuntime()
        {
            string code = Context == null ? string.Empty : Context.Code;
            if (string.IsNullOrWhiteSpace(code))
                _autoTradeController?.ClearProgramFlowSnapshot();
            else
                _autoTradeController?.ClearProgramFlowSnapshot(code);

            Application.Current.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    ProgramTrades.Clear();
                    LatestProgramFlowSnapshot = null;
                }));
        }

        private void RequestProgramTradeSeedIfAvailable(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                return;

            if (_marketApi is KiwoomApiService kiwoomApi)
            {
                kiwoomApi.RequestProgramTradeHistory(WindowId, code, ScreenNo, minutes: 30, priority: 1);
                return;
            }

            if (_marketApi is LocalReplayApiService replayApi)
                replayApi.RequestProgramTradeHistory(WindowId, code, ScreenNo, minutes: 30, priority: 1);
        }

