            _marketApi.OnLogin += Kiwoom_OnLogin;
            _marketApi.OnLog += Kiwoom_OnLog;
            _marketApi.OnSymbolDetected += Kiwoom_OnSymbolDetected;
            _marketApi.OnAiSymbolDetected += OnAiSymbolDetected;
