            _marketApi.OnTickReceived += Kiwoom_OnTickReceived;
            _marketApi.OnHogaReceived += Kiwoom_OnHogaReceived;
            _marketApi.OnHoldingsReceived += Kiwoom_OnHoldingsReceived;
            _marketApi.OnPositionBalanceChanged += Kiwoom_OnPositionBalanceChanged;
            _marketApi.OnOrdersReceived += Kiwoom_OnOrdersReceived;
            _marketApi.OnUnfilledOrdersReceived += Kiwoom_OnUnfilledOrdersReceived;
            _marketApi.OnGlobalUpdateRequired += Kiwoom_OnGlobalUpdateRequired;
            _marketApi.OnOrderFilled += Kiwoom_OnOrderFilled;
            _marketApi.OnRealPriceReceived += Kiwoom_OnRealPriceReceived;
            _marketApi.OnInventoryTickReceived += Kiwoom_OnInventoryTickReceived;
            _marketApi.OnMinuteHistoryReceived += Kiwoom_OnMinuteHistoryReceived;
            _marketApi.OnRecentTicksReceived += Kiwoom_OnRecentTicksReceived;
            _marketApi.OnMarketIndexReceived += Kiwoom_OnMarketIndexReceived;

            if (_marketApi is KiwoomApiService kiwoomApi)
            {
                kiwoomApi.OnConnectionLost += Kiwoom_OnConnectionLost;
                kiwoomApi.OnReconnected += Kiwoom_OnReconnected;
                kiwoomApi.OnProgramTradeReceived += Kiwoom_OnProgramTradeReceived;
            }
            else if (_marketApi is LocalReplayApiService replayApi)
            {
                replayApi.OnProgramTradeReceived += Kiwoom_OnProgramTradeReceived;
            }
        }

