            if (_marketApi is KiwoomApiService kiwoomApi)
            {
                kiwoomApi.OnConnectionLost -= Kiwoom_OnConnectionLost;
                kiwoomApi.OnReconnected -= Kiwoom_OnReconnected;
                kiwoomApi.OnProgramTradeReceived -= Kiwoom_OnProgramTradeReceived;
            }
            else if (_marketApi is LocalReplayApiService replayApi)
            {
                replayApi.OnProgramTradeReceived -= Kiwoom_OnProgramTradeReceived;
            }
        }

