        private readonly object _deferredStartupServicesLock = new object();
        private volatile bool _deferredStartupServicesScheduled;
        private volatile bool _deferredStartupServicesStarted;
        private volatile bool _isDisposingOrDisposed;

        public MainWindowViewModel(IMarketApiService marketApi)
        {
            TradingCostPolicy.SetRates(
                _moneyCreatorEstimatedBuyFeeRate,
                _moneyCreatorEstimatedSellFeeRate,
                _moneyCreatorEstimatedSellTaxRate);

            _marketApi = marketApi ?? throw new ArgumentNullException(nameof(marketApi));
            _isReplayMode = _marketApi is LocalReplayApiService || GlobalApi.Mode == MarketApiMode.Replay;

            Account = new AccountViewModel(this);
            MarketData = new MarketDataViewModel(this);
            Orders = new OrdersViewModel(this);
            AutoTrading = new AutoTradingViewModel(this);

            SubscribeMarketApiEvents();

            ScreenNo = _marketApi.GetScreenNo();

            ConnectCommand = new RelayCommand(async _ => await ExecuteConnect());
            SearchCommand = new RelayCommand(_ => ExecuteSearch());
            AiToggleCommand = new RelayCommand(OpenNewWindow);

            AutoTradingToggleCommand = new RelayCommand(() =>
            {
                bool nextEnabled = !IsAutoTradingEnabled;

                if (nextEnabled && !CanEnableAutoTradingForCurrentSymbol())
                {
                    IsAutoTradingEnabled = false;
                    AddLog("⚠️ 자동매매 ON 차단: 종목코드가 없습니다.");
                    AddAutoTradeAnalysisLog("[자동매매 차단] 종목코드 없음 - Auto OFF 유지");
                    return;
                }

                IsAutoTradingEnabled = nextEnabled;
            });

            ScheduleDeferredStartupServices();
        }

        private void ScheduleDeferredStartupServices()
        {
            if (_isDisposingOrDisposed)
                return;

            lock (_deferredStartupServicesLock)
            {
                if (_deferredStartupServicesScheduled || _deferredStartupServicesStarted)
                    return;

                _deferredStartupServicesScheduled = true;
            }

            Task.Run(async () =>
            {
                try
                {
                    // 화면 첫 표시 전에 DB/성과/자동매매 worker 초기화가 몰리지 않게 한 박자 늦춘다.
                    await Task.Delay(IsReplayMode ? 500 : 1500);

                    if (_isDisposingOrDisposed)
                        return;

                    var dispatcher = Application.Current?.Dispatcher;
                    if (dispatcher == null || dispatcher.HasShutdownStarted || dispatcher.HasShutdownFinished)
                        return;

                    dispatcher.BeginInvoke(
                        DispatcherPriority.Background,
                        new Action(StartDeferredStartupServicesOnUiThread));
                }
                catch (Exception ex)
                {
                    lock (_deferredStartupServicesLock)
                    {
                        if (!_isDisposingOrDisposed && !_deferredStartupServicesStarted)
                            _deferredStartupServicesScheduled = false;
                    }

                    Debug.WriteLine("[시작 지연 초기화 예약 실패] " + ex.Message);
                }
            });
        }

        private void StartDeferredStartupServicesOnUiThread()
        {
            if (_isDisposingOrDisposed)
                return;

            lock (_deferredStartupServicesLock)
            {
                if (_deferredStartupServicesStarted)
                    return;

                _deferredStartupServicesStarted = true;
            }

            try
            {
                if (_isDisposingOrDisposed)
                    return;

                Db?.StartDeferredStartupInitialization();

                if (_isDisposingOrDisposed)
                    return;

                InitializeAutoTrading();
                StartMoneyCreatorPortfolioTimers();
                StartPerformanceMonitor();

                AddAutoTradeAnalysisLog("[시작 지연초기화] 화면 표시 우선 / AutoTradeWorker+성과+ML/Analysis DB 보강 지연 시작");
            }
            catch (Exception ex)
            {
                lock (_deferredStartupServicesLock)
                {
                    _deferredStartupServicesStarted = false;
                    if (!_isDisposingOrDisposed)
                        _deferredStartupServicesScheduled = false;
                }

                Debug.WriteLine("[시작 지연 초기화 실패] " + ex.Message);
                AddAutoTradeAnalysisLog("[시작 지연초기화 실패] " + ex.Message);
            }
        }
