        private bool IsEventForCurrentWindow(string windowId)
        {
            if (string.IsNullOrWhiteSpace(windowId))
                return true;

            if (string.Equals(windowId, WindowId, StringComparison.OrdinalIgnoreCase))
                return true;

            return string.Equals(windowId, "COMMON", StringComparison.OrdinalIgnoreCase) ||
                   string.Equals(windowId, "SYSTEM", StringComparison.OrdinalIgnoreCase);
        }

        private HashSet<string> GetCurrentWindowRuntimeCodes()
        {
            var codes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (Context != null && !string.IsNullOrWhiteSpace(Context.Code))
                codes.Add(Context.Code);

            foreach (var code in _lastAutoTradeHoldingCodes.ToList())
            {
                if (!string.IsNullOrWhiteSpace(code))
                    codes.Add(code);
            }

            if (AccountHoldings != null)
            {
                foreach (var holding in AccountHoldings.ToList())
                {
                    if (holding != null && !string.IsNullOrWhiteSpace(holding.Code))
                        codes.Add(holding.Code);
                }
            }

            if (OrderHistory != null)
            {
                foreach (var order in OrderHistory.ToList())
                {
                    if (order != null && !string.IsNullOrWhiteSpace(order.Code))
                        codes.Add(order.Code);
                }
            }

            return codes;
        }

        private void ClearCurrentWindowAccountRuntimeState(string reason)
        {
            var affectedCodes = GetCurrentWindowRuntimeCodes();

            AccountHoldings.Clear();
            OrderHistory.Clear();
            Context.CurrentHold = null;
            HoldingQty = 0;
            CurrentBalance = 0;

            _lastAutoTradeHoldingCodes.Clear();

            lock (_moneyCreatorPortfolioSyncRoot)
            {
                foreach (var code in affectedCodes)
                {
                    _moneyCreatorLatestFeatureByCode.Remove(code);
                    _moneyCreatorPortfolioAllocationByCode.Remove(code);
                    _moneyCreatorAcceptedBuyReservedByCode.Remove(code);
                    _moneyCreatorLastBuyOrderReservedAtByCode.Remove(code);
                    _moneyCreatorPendingSellRefreshCodes.Remove(code);
                }
            }

            OnPropertyChanged(nameof(AccountHoldings));
            OnPropertyChanged(nameof(OrderHistory));
            OnPropertyChanged(nameof(HoldingQty));
            OnPropertyChanged(nameof(CurrentBalance));
            OnPropertyChanged(nameof(TradeCardHoldingQty));

            AddLog($"🧹 현재 창 계좌/보유/자산배분 상태 초기화: {reason}");
        }


        private async Task RequestInitialAccountReloadAfterReplayOff()
        {
            if (_marketApi == null)
                return;

            if (string.IsNullOrWhiteSpace(SelectedAccount))
            {
                FetchAccountList();

                if (string.IsNullOrWhiteSpace(SelectedAccount))
                {
                    AddLog("⚠️ ReplayMode OFF: 계좌번호가 없어 계좌 초기 로딩을 건너뜁니다.");
                    return;
                }

            }

            ResetInitialMainLoadingState();
            BeginInitialMainLoading();

            _marketApi.RequestAccountHoldings(WindowId, SelectedAccount, ScreenNo);
            await Task.Delay(300);

            _marketApi.RequestCashInfo(WindowId, SelectedAccount, ScreenNo);
            await Task.Delay(300);

            _marketApi.RequestOrderHistory(WindowId, SelectedAccount, ScreenNo);
        }

        private Task ReloadRealModeSymbolDataAfterReplayOff(string code, string name, double lastPrice)
        {
            if (_marketApi == null || string.IsNullOrWhiteSpace(code))
                return Task.CompletedTask;

            Context.SwitchSymbol(code, string.IsNullOrWhiteSpace(name) ? code : name, lastPrice);

            MarkAutoTradeDataNotReady(code);
            _autoTradeController?.Reset(code);

            ResetRealtimeTickWindow();
            _minuteHistoryBuffer.Clear();
            ClearProgramTradeRuntime();

            CheckHoldingStatus();

            _marketApi.ReplaceSubscription(WindowId, ScreenNo, code);
            RequestProgramTradeSeedIfAvailable(code);

            _marketApi.RequestMinuteCandles(
                WindowId,
                code,
                ScreenNo,
                daysToLoad: 2,
                maxRows: 0,
                priority: 0);

            IsLoading = false;
            IsSearchPopupOpen = false;

            AddLog($"📊 ReplayMode OFF: 실거래 분봉 재요청 / 최근틱은 분봉 완료 후 기존 흐름으로 요청: {code}");
            return Task.CompletedTask;
        }

        private void EnableReplayModeOnCurrentWindow()
        {
            ForceAutoTradingOffAndSmallScale("ReplayMode ON");

            if (!(_marketApi is LocalReplayApiService))
            {
                _liveMarketApiBeforeReplay = _marketApi;
                SwitchMarketApi(new LocalReplayApiService(_liveMarketApiBeforeReplay));
            }

            _isReplayMode = true;
            SyncAutoTradeReplayModeSetting("ReplayMode ON");
            ResetReplayAutoSessionLifecycleState("ReplayMode ON");
            OnPropertyChanged(nameof(IsReplayMode));
            OnPropertyChanged(nameof(ReplayModeStatusText));

            ResetCurrentWindowForReplay("ReplayMode ON");
            ClearCurrentWindowAccountRuntimeState("ReplayMode ON");

            if (_marketApi is LocalReplayApiService replayApi)
                replayApi.ResetReplaySession(WindowId);

            AddLog("🧪 ReplayMode ON: Auto OFF / SmallScale ON / 현재 창을 초기화했습니다. 종목 선택 후 Auto ON 시 Replay Tick을 재생합니다.");
        }

        private async void DisableReplayModeOnCurrentWindow()
        {
            string reloadCode = Context == null ? string.Empty : Context.Code;
            string reloadName = Context == null ? string.Empty : Context.Name;
            double reloadPrice = Context == null ? 0 : Context.LastPrice;

            ForceAutoTradingOffAndSmallScale("ReplayMode OFF");

            if (_marketApi is LocalReplayApiService replayApi)
            {
                replayApi.StopReplay(WindowId);
                FinalizeReplayAutoTradingForModeOff("ReplayMode OFF");
                replayApi.ResetReplaySession(WindowId);
            }
            else
            {
                FinalizeReplayAutoTradingForModeOff("ReplayMode OFF");
            }

            ResetCurrentWindowForReplay("ReplayMode OFF");
            ClearCurrentWindowAccountRuntimeState("ReplayMode OFF");

            _isReplayMode = false;
            SyncAutoTradeReplayModeSetting("ReplayMode OFF");
            OnPropertyChanged(nameof(IsReplayMode));
            OnPropertyChanged(nameof(ReplayModeStatusText));

            if (_liveMarketApiBeforeReplay != null)
            {
                SwitchMarketApi(_liveMarketApiBeforeReplay);
                _liveMarketApiBeforeReplay = null;
            }
            else if (_marketApi is LocalReplayApiService)
            {
                SwitchMarketApi(KiwoomApiService.Instance);
            }

            await RequestInitialAccountReloadAfterReplayOff();
            await Task.Delay(300);
            await ReloadRealModeSymbolDataAfterReplayOff(reloadCode, reloadName, reloadPrice);

            AddLog("🧪 ReplayMode OFF: Auto OFF / SmallScale ON / 현재 창·자동매매·차트 초기화 후 실거래 초기 로딩을 다시 요청했습니다.");
        }

        private void SwitchMarketApi(IMarketApiService newApi)
        {
            if (newApi == null || ReferenceEquals(_marketApi, newApi))
                return;

            UnsubscribeMarketApiEvents();
            _marketApi?.UnregisterWindow(WindowId);

            _marketApi = newApi;
            ScreenNo = _marketApi.GetScreenNo();

            SyncAutoTradeReplayModeSetting("MarketApi 전환");

            SubscribeMarketApiEvents();

            if (_marketApi is LocalReplayApiService)
                _marketApi.Login();
            else if (_marketApi.IsConnected())
                HandleAlreadyLoggedIn();
            else
                _marketApi.Login();
        }

        private void ResetCurrentWindowForReplay(string reason)
        {
            string oldCode = Context == null ? string.Empty : Context.Code;

            if (!string.IsNullOrWhiteSpace(oldCode))
                MarkAutoTradeDataNotReady(oldCode);
            else
                MarkAutoTradeDataNotReady();

            _autoTradeController?.Reset();
            ResetRealtimeTickWindow();
            ResetTradeAnalysisCard();
            AutoTradeAnalysisLogs.Clear();

            AccountHoldings.Clear();
            OrderHistory.Clear();
            Context.CurrentHold = null;
            _lastAutoTradeHoldingCodes.Clear();
            AskList.Clear();
            BidList.Clear();
            _tradeMarkerKeys.Clear();
            _realTimeBuffer.Clear();
            _minuteTickBuffer.Clear();
            _minuteHistoryBuffer.Clear();

            HoldingQty = 0;
            TotalAskQty = 0;
            TotalBidQty = 0;
            _latestHogaForAutoTrade = null;
            _lastHogaUiUpdateTime = DateTime.MinValue;
            _isHistoryBindingComplete = false;

            ClearBuffer();
            OnChartResetRequired?.Invoke();

            AddLog($"🧹 현재 창/자동매매/차트 초기화 완료: {reason}");
        }

        private async Task<bool> PrepareReplayDataForCurrentSymbolAsync(string code)
        {
            if (!IsReplayMode)
                return true;

            if (string.IsNullOrWhiteSpace(code))
            {
                MessageBox.Show("종목코드가 없습니다. 종목을 먼저 선택하세요.", "ReplayMode", MessageBoxButton.OK, MessageBoxImage.Warning);
                return false;
            }

            if (!(_marketApi is LocalReplayApiService replayApi))
                return false;

            MainLoadingMessage = $"Replay 원천데이터 준비 중: {code}";
            IsMainLoading = true;

            var result = await replayApi.PrepareReplayDataAsync(WindowId, code).ConfigureAwait(true);

            IsMainLoading = false;
            MainLoadingMessage = string.Empty;

            if (result == null || !result.IsReady)
            {
                MessageBox.Show(
                    $"Replay 데이터가 부족합니다.\n종목: {code}\n{result?.Message ?? "원천 데이터 없음"}",
                    "ReplayMode",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return false;
            }

            return true;
        }

        private void ApplyReplayAutoTradingState(bool enabled)
        {
            if (!IsReplayMode)
                return;

            if (!(_marketApi is LocalReplayApiService replayApi))
                return;

            string code = Context == null ? string.Empty : Context.Code;
            if (string.IsNullOrWhiteSpace(code))
            {
                replayApi.PauseReplay(WindowId);
                return;
            }

            if (enabled)
            {
                replayApi.StartOrResumeReplay(WindowId, code);
                AddLog($"▶ Replay Tick 재생 시작: {code} / Auto ON");
            }
            else
            {
                replayApi.PauseReplay(WindowId);
                AddLog($"⏸ Replay Tick 일시정지: {code} / Auto OFF / pending 유지");
            }
        }


