        private void Kiwoom_OnSymbolDetailUpdated(string wId, Symbol updatedSymbol)
        {
            if (wId != this.WindowId) return;

            // Dispatcher 밖에서 미리 계산
            double lastPriceNum = 0;
            double.TryParse(updatedSymbol.LastPrice.Replace(",", ""), out lastPriceNum);

            Application.Current.Dispatcher.BeginInvoke(new Action(() =>
            {
                var target = SearchResults.FirstOrDefault(s => s.Code == updatedSymbol.Code);
                if (target != null)
                {
                    target.LastPrice = updatedSymbol.LastPrice;
                    target.Change = updatedSymbol.Change;
                }

                if (updatedSymbol.Code == Context.Code)
                {
                    Context.LastPrice = lastPriceNum;
                }
            }));
        }
