        public bool IsConnected()
        {
            if (_api == null) return false;

            try
            {
                // GetConnectState() 리턴값: 0(미연결), 1(연결완료)
                return _api.GetConnectState() == 1;
            }
            catch (System.Runtime.InteropServices.InvalidComObjectException ex)
            {
                Debug.WriteLine("[키움 연결상태 확인 실패] RCW 분리: " + ex.Message);
                return false;
            }
            catch (ObjectDisposedException ex)
            {
                Debug.WriteLine("[키움 연결상태 확인 실패] ActiveX Dispose: " + ex.Message);
                return false;
            }
            catch (Exception ex)
            {
                Debug.WriteLine("[키움 연결상태 확인 실패] " + ex.Message);
                return false;
            }
        }
        public void AddLog(string msg)
        {
            try
            {
                Application.Current?.Dispatcher.BeginInvoke(new Action(() =>
                {
                    Logs.Insert(0, $"[{DateTime.Now:HH:mm:ss}] {msg}");
                    if (Logs.Count > 100) Logs.RemoveAt(100);
                }));
            }
            catch { }
        }
