        private bool _tickAnalysisLogFlushScheduled;
        private readonly object _tickAnalysisLogUiLock = new object();
        private const int AutoTradeAnalysisLogUiRefreshIntervalMs = 1000;
        private const int MaxAutoTradeAnalysisLogCount = 3000;

        public void AddAutoTradeAnalysisLog(string msg)
        {
            if (string.IsNullOrWhiteSpace(msg))
                return;

            bool isTickAnalysis = msg.StartsWith("[틱분석]");
            bool isOrderFlow = msg.StartsWith("[주문흐름]");
            bool isTradeSignal =
                msg.Contains("판단=Buy") ||
                msg.Contains("판단=Sell") ||
                msg.Contains("Action=Buy") ||
                msg.Contains("Action=Sell");

            // Stage179:
            // [틱분석] 로그는 Replay/Real 여부와 Buy/Sell/Hold 여부에 상관없이 전부 표시한다.
            // 초당 1건으로 모으면 평단/체결/슬리피지 같은 데이터 무결성 원인을 추적할 수 없다.
            // 트레이딩 카드/점수차트의 1초 UI 제한은 QueueAnalysisUiUpdate 경로에만 유지한다.
            if (isTickAnalysis)
            {
                AppendAutoTradeAnalysisLogUi(msg);
                return;
            }

            if (!isOrderFlow && !isTradeSignal)
            {
                if ((DateTime.Now - _lastAnalysisLogTime).TotalMilliseconds < 500)
                    return;

                _lastAnalysisLogTime = DateTime.Now;
            }

            AppendAutoTradeAnalysisLogUi(msg);
        }

        private void QueueTickAnalysisLogUiUpdate(string msg)
        {
            bool shouldSchedule = false;

            lock (_tickAnalysisLogUiLock)
            {
                _pendingTickAnalysisLogMessage = msg;

                if (!_tickAnalysisLogFlushScheduled)
                {
                    _tickAnalysisLogFlushScheduled = true;
                    shouldSchedule = true;
                }
            }

            if (shouldSchedule)
                ScheduleTickAnalysisLogUiFlush();
        }

        private void ScheduleTickAnalysisLogUiFlush()
        {
            var dispatcher = Application.Current?.Dispatcher;
            if (dispatcher == null)
            {
                FlushPendingTickAnalysisLogUi();
                return;
            }

            dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    int delayMs = ResolveTickAnalysisLogUiFlushDelayMilliseconds();

                    if (delayMs <= 0)
                    {
                        FlushPendingTickAnalysisLogUi();
                        return;
                    }

                    var timer = new DispatcherTimer(DispatcherPriority.Background, dispatcher)
                    {
                        Interval = TimeSpan.FromMilliseconds(delayMs)
                    };

                    timer.Tick += (s, e) =>
                    {
                        timer.Stop();
                        FlushPendingTickAnalysisLogUi();
                    };

                    timer.Start();
                }));
        }

        private int ResolveTickAnalysisLogUiFlushDelayMilliseconds()
        {
            if (_lastTickAnalysisLogUiFlushAt == DateTime.MinValue)
                return 0;

            double elapsedMs = (DateTime.Now - _lastTickAnalysisLogUiFlushAt).TotalMilliseconds;
            int delayMs = AutoTradeAnalysisLogUiRefreshIntervalMs - (int)elapsedMs;

            return delayMs <= 0 ? 0 : delayMs;
        }

        private void FlushPendingTickAnalysisLogUi()
        {
            string msg;

            lock (_tickAnalysisLogUiLock)
            {
                msg = _pendingTickAnalysisLogMessage;
                _pendingTickAnalysisLogMessage = null;
                _tickAnalysisLogFlushScheduled = false;
                _lastTickAnalysisLogUiFlushAt = DateTime.Now;
            }

            if (string.IsNullOrWhiteSpace(msg))
                return;

            AppendAutoTradeAnalysisLogUi(msg);
        }

        private void AppendAutoTradeAnalysisLogUi(string msg)
        {
            Application.Current?.Dispatcher.BeginInvoke(
                DispatcherPriority.Background,
                new Action(() =>
                {
                    // 트레이딩 카드는 FeatureSnapshot 기반 분석 갱신 경로에서만 갱신한다.
                    // 로그 문자열 기반 갱신은 일부 필드가 없는 로그가 들어올 때 카드 값을 "-"로 덮어써
                    // 카드가 계속 클리어되는 것처럼 보일 수 있으므로 여기서는 로그 목록만 갱신한다.
                    AutoTradeAnalysisLogs.Insert(0, msg);

                    while (AutoTradeAnalysisLogs.Count > MaxAutoTradeAnalysisLogCount)
                        AutoTradeAnalysisLogs.RemoveAt(AutoTradeAnalysisLogs.Count - 1);

                    AutoTradeAnalysisLogFileWriter.Enqueue(
                        Context == null ? string.Empty : Context.Code,
                        Context == null ? string.Empty : Context.Name,
                        ResolveAutoTradeAnalysisLogModeSuffix(),
                        ResolveAutoTradeAnalysisLogFallbackDate(),
                        msg);
                }));
        }
        private string ResolveAutoTradeAnalysisLogModeSuffix()
        {
            return IsReplayMode ? "Replay" : "Real";
        }

        private DateTime ResolveAutoTradeAnalysisLogFallbackDate()
        {
            if (IsReplayMode && _marketApi is LocalReplayApiService replayApi)
            {
                if (replayApi.ReplayNow != DateTime.MinValue)
                    return replayApi.ReplayNow.Date;

                if (replayApi.ReplayTradingDate != DateTime.MinValue)
                    return replayApi.ReplayTradingDate.Date;
            }

            return DateTime.Now.Date;
        }
