        public void Dispose()
        {
            if (_isDisposingOrDisposed)
                return;

            _isDisposingOrDisposed = true;

            try
            {
                // 종료 중에는 새 실시간/주문/분석 이벤트가 들어오지 않게 먼저 끊는다.
                // AutoTradeController Dispose와 DB Flush 순서는 기존 흐름을 유지한다.
                UnsubscribeMarketApiEvents();
                StopDecisionCandidateOutcomePumpTimer();
            }
            catch (Exception ex)
            {
                Debug.WriteLine("[종료 전 이벤트/타이머 정리 실패] " + ex.Message);
            }

            Account?.Dispose();
            MarketData?.Dispose();
            Orders?.Dispose();
            AutoTrading?.Dispose();

            FlushDbOnClose();
            AutoTradeAnalysisLogFileWriter.FlushAll();
            Cleanup();

            _marketApi?.UnregisterWindow(WindowId);

            if (Context != null && !string.IsNullOrWhiteSpace(Context.Code))
            {
                string key = $"{WindowId}_{Context.Code}";
                _requestTokens.TryRemove(key, out _);
            }
        }

