        private bool FocusOpenedSymbolWindow(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                return false;

            foreach (Window w in Application.Current.Windows)
            {
                if (w.DataContext is MainWindowViewModel vm)
                {
                    // 현재 창 자신
                    if (w == this.HostWindow)
                    {
                        // 현재 창이 이미 이 종목을 보고 있을 때만 중복 처리
                        if (vm.Context.Code == code)
                        {
                            AddLog($"ℹ️ 현재 창에서 이미 열린 종목: {code}");
                            return true;
                        }

                        continue;
                    }

                    // 다른 창은 Tag 또는 Context.Code로 판단
                    if ((w.Tag as string) == code || vm.Context.Code == code)
                    {
                        if (w.WindowState == WindowState.Minimized)
                            w.WindowState = WindowState.Normal;

                        w.Activate();
                        w.Focus();

                        AddLog($"🔎 이미 열린 종목 창으로 이동: {code}");
                        return true;
                    }
                }
            }

            return false;
        }
